#include <iostream>
#include <string>

#include "../server/server.hpp"
#include "handlers.hpp"

using namespace std;

void mapServerPaths(Server& server, System* &system) {
    server.setNotFoundErrPage("static/404.html");
    // server.get("/", new ShowPage("static/home.html"));
    // server.get("/home.png", new ShowImage("static/home.png"));
    //server.get("/rand", new RandomNumberHandler());
    server.get("/", new ShowPage("static/logincss.html"));
    server.post("/login", new LoginHandler(system));
    server.get("/error1", new ShowPage("static/error1.html"));
    server.get("/error2", new ShowPage("static/error2.html"));
    server.get("/error3", new ShowPage("static/error3.html"));
    server.get("/error4", new ShowPage("static/error4.html"));
    server.get("/student", new StudentPageHandler(system));
    server.get("/professor", new ProfessorPageHandler(system));
    server.get("/manager", new ManagerPageHandler(system));
    server.get("/send_post", new ShowPage("static/postcss.html"));
    server.post("/send_post", new PostHandler(system));


    server.get("/up", new ShowPage("static/upload_form.html"));
    server.post("/up", new UploadHandler());
    server.get("/colors", new ColorHandler("template/colors.html"));
    server.get("/music", new ShowPage("static/music.html"));
    server.get("/music/moonlight.mp3", new ShowFile("static/moonlight.mp3", "audio/mpeg"));
}

int main(int argc, char* argv[]) {
    System* system = new System(argv[1], argv[2], argv[3], argv[4]);
    Server server(5000);
    mapServerPaths(server, system);
    server.run();
    return 0;
}
